            timeout_minutes: 25
          - name: macOS arm64
            runner: macos-15
            timeout_minutes: 25
          - name: macOS x64
            runner: macos-15-intel
            timeout_minutes: 25
          - name: Windows x64
            runner: windows-2025
            timeout_minutes: 45
