/**
 * Skills search / install via skills.sh API or ELECTRON_RUN_AS_NODE npx.
 */
import { runNpx } from "./npx";
import type { SkillSearchResult } from "../shared/api-types";
import { ToolchainError } from "../shared/toolchains/errors.ts";
import { buildSkillsCliArgs } from "./skills-cli.ts";
import { normalizeSkillsApiResults, parseSkillsSearchOutput } from "./skills-search.ts";

const ANSI_RE = /\x1B\[[0-9;]*m/g;
const SEARCH_API_BASE = process.env.SKILLS_API_URL || "https://skills.sh";

async function searchSkillsApi(query: string, limit: number): Promise<SkillSearchResult[]> {
  const url = `${SEARCH_API_BASE}/api/search?q=${encodeURIComponent(query)}&limit=${limit}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`skills.sh search failed: HTTP ${res.status}`);
  const data = (await res.json()) as {
    skills?: Array<{ id?: string; name?: string; source?: string; installs?: number }>;
  };
  return normalizeSkillsApiResults(data.skills ?? [], SEARCH_API_BASE);
}

export async function searchSkills(query: string, limit = 50): Promise<{ results: SkillSearchResult[] }> {
  const q = query.trim();
  if (!q) return { results: [] };
  const capped = Math.min(50, Math.max(1, limit));

  try {
    const results = await searchSkillsApi(q, capped);
    return { results };
  } catch {
    const { stdout, stderr } = await runNpx(buildSkillsCliArgs(["find", q]), {
      timeout: 60_000,
      env: { FORCE_COLOR: "0" },
    });
    return { results: parseSkillsSearchOutput(stdout + stderr).slice(0, capped) };
  }
}

export async function installSkill(params: {
  package: string;
  scope?: "global" | "project";
  cwd?: string;
}): Promise<{ ok: true; output: string }> {
  const pkg = params.package?.trim();
  if (!pkg) throw new Error("package required");

  const isGlobal = params.scope !== "project";
  const args = buildSkillsCliArgs(["add", pkg, "-y", "--agent", "pi"]);
  if (isGlobal) args.push("-g");

  try {
    const { stdout, stderr } = await runNpx(args, {
      timeout: 180_000,
      cwd: !isGlobal && params.cwd ? params.cwd : undefined,
      env: { FORCE_COLOR: "0" },
    });
    const output = (stdout + stderr).replace(ANSI_RE, "");
    const success = /Installation complete|Installed \d+ skill/.test(output);
    if (!success) throw new Error(output.slice(-300) || "Install failed");
    return { ok: true as const, output };
  } catch (e: unknown) {
    if (e instanceof ToolchainError) throw e;
    const err = e as { stdout?: string; stderr?: string; message?: string };
    const output = ((err.stdout ?? "") + (err.stderr ?? "")).replace(ANSI_RE, "");
    throw new Error(output || err.message || String(e));
  }
}
const SKILLS_CLI_PACKAGE = "skills@1.5.22";

export function buildSkillsCliArgs(args: string[]): string[] {
  // Pin the executable package so a failed unversioned npx install cannot
  // poison every later invocation under the same shared cache key.
  return ["--yes", "--package", SKILLS_CLI_PACKAGE, "--", "skills", ...args];
}
import type { SkillSearchResult } from "../shared/api-types.ts";

const ANSI_RE = /\x1B\[[0-9;]*m/g;

function parseInstallCount(installs: string): number {
  const match = installs.match(/^([\d.,]+)([KMB])?\s+installs?$/);
  if (!match) return 0;
  const value = Number(match[1].replaceAll(",", ""));
  if (!Number.isFinite(value)) return 0;
  const multiplier = match[2] === "B" ? 1_000_000_000 : match[2] === "M" ? 1_000_000 : match[2] === "K" ? 1_000 : 1;
  return value * multiplier;
}

export function parseSkillsSearchOutput(raw: string): SkillSearchResult[] {
  const clean = raw.replace(ANSI_RE, "");
  const results: SkillSearchResult[] = [];
  const lines = clean.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    const packageMatch = line.match(/^([\w.\-]+\/[\w.\-@:]+)\s+([\d.,]+[KMB]?\s+installs)$/);
    if (!packageMatch) continue;
    const urlLine = lines[i + 1]?.trim().replace(/^└\s*/, "");
    results.push({
      package: packageMatch[1],
      installs: parseInstallCount(packageMatch[2]),
      url: urlLine?.startsWith("https://") ? urlLine : "",
    });
  }
  return results;
}

export function normalizeSkillsApiResults(
  skills: Array<{ id?: string; name?: string; source?: string; installs?: number }>,
  searchApiBase: string,
): SkillSearchResult[] {
  return skills
    .map((skill) => {
      const name = skill.name?.trim();
      const source = skill.source?.trim();
      const slug = skill.id?.trim();
      if (!name || (!source && !slug)) return null;
      return {
        package: `${source || slug}@${name}`,
        installs: Number.isFinite(skill.installs) && (skill.installs ?? 0) > 0 ? (skill.installs ?? 0) : 0,
        url: slug ? `${searchApiBase}/${slug}` : "",
      };
    })
    .filter((result): result is SkillSearchResult => result !== null)
    .sort((a, b) => b.installs - a.installs);
}
import { isMap, parseDocument } from "yaml";

const MODEL_INVOCATION_KEY = "disable-model-invocation";

type FrontmatterBlock = {
  yaml: string;
  body: string;
  openingNewline: string;
  closingNewline: string;
};

function splitFrontmatter(content: string): FrontmatterBlock | undefined {
  const openingNewline = content.startsWith("---\r\n") ? "\r\n" : content.startsWith("---\n") ? "\n" : undefined;
  if (!openingNewline) return undefined;

  const yamlStart = 3 + openingNewline.length;
  let lineStart = yamlStart;
  while (lineStart <= content.length) {
    const lineFeed = content.indexOf("\n", lineStart);
    const lineEnd = lineFeed === -1 ? content.length : lineFeed;
    const rawLine = content.slice(lineStart, lineEnd);
    const line = rawLine.endsWith("\r") ? rawLine.slice(0, -1) : rawLine;
    if (line === "---") {
      const closingNewline = lineFeed === -1 ? "" : rawLine.endsWith("\r") ? "\r\n" : "\n";
      return {
        yaml: content.slice(yamlStart, lineStart),
        body: lineFeed === -1 ? "" : content.slice(lineFeed + 1),
        openingNewline,
        closingNewline,
      };
    }
    if (lineFeed === -1) break;
    lineStart = lineFeed + 1;
  }
  return undefined;
}

export function updateSkillModelInvocation(content: string, disabled: boolean): string {
  const block = splitFrontmatter(content);
  if (!block) {
    if (!disabled) return content;
    const newline = content.includes("\r\n") ? "\r\n" : "\n";
    return `---${newline}${MODEL_INVOCATION_KEY}: true${newline}---${newline}${content}`;
  }

  const document = parseDocument(block.yaml);
  if (document.errors.length > 0) throw document.errors[0];
  if (!isMap(document.contents)) throw new Error("Skill frontmatter must be a YAML mapping");

  const hasKey = document.has(MODEL_INVOCATION_KEY);
  if ((disabled && document.get(MODEL_INVOCATION_KEY) === true) || (!disabled && !hasKey)) return content;
  if (disabled) document.set(MODEL_INVOCATION_KEY, true);
  else document.delete(MODEL_INVOCATION_KEY);

  const serialized = document.toString({ lineWidth: 0 }).replace(/\n$/, "").replace(/\n/g, block.openingNewline);
  return `---${block.openingNewline}${serialized}${block.openingNewline}---${block.closingNewline}${block.body}`;
}
import type { AgentSessionRuntimeDiagnostic } from "@earendil-works/pi-coding-agent";

export type ExtensionDiagnosticStatus = { key: string; text: string };

function safeDiagnosticMessage(message: string): string {
  return message
    .replace(/\b(sk-[A-Za-z0-9_-]{8,}|gh[pousr]_[A-Za-z0-9_]{8,})\b/g, "[redacted]")
    .replace(/\b(api[_ -]?key|token|authorization)(\s*[:=]\s*)[^\s,;]+/gi, "$1$2[redacted]")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 240);
}

export function projectExtensionDiagnostics(
  diagnostics: readonly AgentSessionRuntimeDiagnostic[],
): ExtensionDiagnosticStatus[] {
  return diagnostics.map((diagnostic, index) => ({
    key: `pi-runtime-${diagnostic.type}-${index + 1}`,
    text: safeDiagnosticMessage(diagnostic.message) || `Pi runtime ${diagnostic.type}`,
  }));
}
import path from "node:path";
import { publicToolchainError } from "../shared/toolchains/errors.ts";
import type { PluginWorkerRequest, PluginWorkerResponse } from "./plugin-worker-protocol.ts";
import { PLUGIN_WORKER_RESULT_MARKER } from "./plugin-worker-protocol.ts";
import { applyPluginActionInProcess } from "./plugins-service";

const MAX_REQUEST_BYTES = 64 * 1024;
const VALID_ACTIONS = new Set(["install", "remove", "update", "disable", "enable"]);

function writeResponse(response: PluginWorkerResponse): void {
  const encoded = Buffer.from(JSON.stringify(response), "utf8").toString("base64");
  process.stdout.write(`\n${PLUGIN_WORKER_RESULT_MARKER}${encoded}\n`);
}

function validateRequest(value: unknown): PluginWorkerRequest {
  if (!value || typeof value !== "object") throw new Error("Invalid Plugin worker request");
  const request = value as PluginWorkerRequest;
  const body = request.body;
  if (
    !body ||
    typeof body.cwd !== "string" ||
    !path.isAbsolute(body.cwd) ||
    body.cwd.length > 4_096 ||
    /[\0\r\n]/.test(body.cwd) ||
    !VALID_ACTIONS.has(body.action)
  ) {
    throw new Error("Invalid Plugin worker action");
  }
  if (body.source !== undefined && (typeof body.source !== "string" || body.source.length > 8_192)) {
    throw new Error("Invalid Plugin source");
  }
  if (
    request.npmCommand !== undefined &&
    (!Array.isArray(request.npmCommand) ||
      request.npmCommand.length < 1 ||
